CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE merchants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id varchar(64) NOT NULL UNIQUE, name varchar(128) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), key_hash varchar(256) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_endpoints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), url varchar(2048) NOT NULL, secret_hash varchar(256) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id varchar(64) NOT NULL UNIQUE, merchant_id uuid NOT NULL REFERENCES merchants(id), merchant_order_reference varchar(128) NOT NULL, idempotency_key varchar(128) NOT NULL, status varchar(32) NOT NULL CHECK (status IN ('created','awaiting_payment','transaction_submitted','confirming','paid','expired','underpaid','overpaid_review','failed','cancelled')), fiat_amount varchar(40) NOT NULL, fiat_currency varchar(3) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(merchant_id, merchant_order_reference), UNIQUE(merchant_id, idempotency_key));
CREATE TABLE quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), rail_id varchar(32) NOT NULL, amount_base_units varchar(80) NOT NULL CHECK (amount_base_units ~ '^[0-9]+$'), rate varchar(80) NOT NULL, rate_source varchar(128) NOT NULL, destination varchar(128) NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), network varchar(32) NOT NULL, hash varchar(128) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(network, hash));
CREATE TABLE payment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), type varchar(64) NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verification_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_transaction_id uuid NOT NULL REFERENCES payment_transactions(id), result varchar(32) NOT NULL, evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verification_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_transaction_id uuid NOT NULL UNIQUE REFERENCES payment_transactions(id), attempts varchar(8) NOT NULL DEFAULT '0', due_at timestamptz NOT NULL, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), type varchar(64) NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), webhook_event_id uuid NOT NULL REFERENCES webhook_events(id), endpoint_id uuid NOT NULL REFERENCES webhook_endpoints(id), due_at timestamptz NOT NULL, lease_until timestamptz, attempts varchar(8) NOT NULL DEFAULT '0', response_status varchar(8), response_excerpt varchar(512), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_jobs_due_idx ON verification_jobs(due_at) WHERE lease_until IS NULL;
CREATE INDEX webhook_deliveries_due_idx ON webhook_deliveries(due_at) WHERE lease_until IS NULL;